    saveSplitterValueInStorage() {
      LocalStorage.set('image_field_splitter', this.imageFieldSplitter);
    },

    getSplitterValueFromStorage() {
      this.imageFieldSplitter = LocalStorage.getItem('image_field_splitter');
      if (!this.imageFieldSplitter) {
        this.imageFieldSplitter = 35;
      }
    },

    async getSplitterValue() {
      try {
        const response = await userApiService.getOrgPreference({
          key: IMAGE_FIELDS_SPLITTER,
        });
        if (!response) {
          return;
        }
        this.imageFieldSplitter = response;
      } catch (err) {
        logError('something went wrong while getSplitterValue', err);
      }
    },

    saveSplitterValue() {
      try {
        const settings_store = useSettingStore();
        settings_store.updateSetting(
          IMAGE_FIELDS_SPLITTER,
          this.imageFieldSplitter,
        );
      } catch (err) {
        logError('something went wrong while saveSplitterValue', err);
      }
    },
