<template>
  <q-card
    flat
    class="page-background container-height full-width"
  >
    <q-card-section class="row justify-center q-pl-md q-pr-md q-pt-md">
      <span class="secondary-c-text text-h6 text-weight-bold">
        {{ $t('support_ticket') }}
      </span>
    </q-card-section>

    <q-separator />

    <q-card-section class="q-pa-md">
      <div class="q-mt-md">
        <!-- Name input -->
        <q-input
          dense
          outlined
          v-model="supportTicket.fullname"
          class="back-white"
          :label="$t('name')"
        />
      </div>

      <div class="q-mt-md">
        <!-- Email input -->
        <q-input
          dense
          outlined
          v-model="supportTicket.email"
          class="back-white"
          :label="$t('email')"
        />
      </div>

      <div class="q-mt-md">
        <!-- Subject input -->
        <q-input
          dense
          outlined
          v-model="supportTicket.subject"
          class="back-white"
          :label="$t('subject')"
        />
      </div>

      <div class="q-mt-md">
        <q-select
          dense
          outlined
          :options="priorityOptions"
          class="back-white"
          v-model="supportTicket.priority"
          :label="$t('priority')"
        />
      </div>

      <div class="q-mt-md">
        <!-- message input -->
        <q-input
          dense
          outlined
          v-model="supportTicket.message"
          class="back-white"
          :label="$t('message')"
          type="textarea"
        />
      </div>

      <div class="q-mt-md">
        <div id="screen-button" class="text-center">
          <f-btn
            :loading="loading"
            class="full-width"
            appearance="secondary"
            :label="$t('screenshot')"
            @click="takeScreenshot()"
          >
            <template v-slot:loading>
              <q-spinner-hourglass class="on-left" />
            </template>
          </f-btn>
        </div>
        <div id="display"></div>
        <!-- message input -->
      </div>

      <div class="q-mt-md">
        <q-file
          outlined
          class="back-white"
          :label="$t('upload_file')"
          v-model="supportTicket.file"
        >
          <template v-slot:prepend>
            <q-icon name="attach_file" />
          </template>
        </q-file>
      </div>
    </q-card-section>

    <q-card-actions align="center" class="q-pb-md">
      <f-btn
        color="primary"
        unelevated
        :label="$t('send')"
        @click="sendSupportTicket"
      />
    </q-card-actions>
  </q-card>
</template>

<script lang="ts">
import { supportApiService } from 'src/services';
import html2canvas from 'html2canvas';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import { defineComponent, ref } from 'vue';
import { i18n } from 'src/boot/i18n';
import { LocalStorage } from 'quasar';
import type { dynamicObj } from 'src/pages/assets';
import { notify } from 'src/components/notifications/notify';

export default defineComponent({
  mixins: [helperMixin],
  setup() {
    return {
      loading: ref(false),
      supportDialog: ref(false),
      priorityOptions: ref([
        { label: i18n.t('very_high'), value: 'Very High' },
        { label: i18n.t('high'), value: 'High' },
        { label: i18n.t('medium'), value: 'Medium' },
        { label: i18n.t('low'), value: 'Low' },
      ]),
      supportTicket: ref({
        email: '',
        message: '',
        subject: '',
        screenshot: '',
        file: '',
        priority: { label: i18n.t('medium'), value: 'Medium' },
      } as any),
    };
  },
  mounted() {
    this.autofillmail();
  },
  methods: {
    autofillmail() {
      let userdatafromlocalstorage: dynamicObj = LocalStorage.getItem(
        'user_details',
      ) as dynamicObj;
      this.supportTicket.email = userdatafromlocalstorage.username;
      this.supportTicket.fullname =
        userdatafromlocalstorage.first_name +
        ' ' +
        userdatafromlocalstorage.last_name;
    },
    takeScreenshot() {
      this.loading = true;
      html2canvas(document.body, { allowTaint: true, useCORS: true }).then(
        (canvas) => {
          var imgBase64 = canvas.toDataURL();
          fetch(imgBase64)
            .then((res) => res.blob())
            .then((blob) => {
              const file = new File([blob], 'Screenshot.png', {
                type: 'image/png',
              });
              this.supportTicket.screenshot = file;
            });
          canvas.style.width = '208px';
          canvas.style.height = '144px';
          this.loading = false;
          logInfo(document.getElementById('display')?.appendChild(canvas));
          document
            .getElementById('screen-button')
            ?.removeChild(
              document.getElementById('screen-button')?.firstChild as Node,
            );
          const messageHTMLElement = document.createElement('span');
          messageHTMLElement.innerHTML = i18n.t(
            'pages.support.screenshot_taken',
          );
          messageHTMLElement.style.color = 'green';
          document
            .getElementById('screen-button')
            ?.appendChild(messageHTMLElement);
        },
      );
    },
    checkArrayForEmptyString() {
      return (
        this.supportTicket.email === '' ||
        this.supportTicket.message === '' ||
        this.supportTicket.fullname === '' ||
        this.supportTicket.subject === ''
      );
    },
    checkStringIfValidEmail() {
       
      return this.supportTicket.email.includes('@');
    },
    buildRequestBody() {
      const formData = new FormData();
      formData.append('fullname', this.supportTicket.fullname);
      formData.append('customer_email', this.supportTicket.email);
      formData.append('subject', this.supportTicket.subject);
      formData.append('priority', this.supportTicket.priority.value);
      formData.append(
        'body',
        this.supportTicket.message + '. DocID: ' + this.$route.params.id,
      );
      if (this.supportTicket.screenshot !== '') {
        formData.append('screenshot', this.supportTicket.screenshot);
      }
      if (this.supportTicket.file !== '') {
        formData.append('attachment', this.supportTicket.file);
      }
      return formData;
    },
    async sendSupportTicket() {
      try {
        this.showLoading();
        if (this.checkArrayForEmptyString()) {
          notify.error(this.$t('fill_all_fields'));
          return;
        }
        if (!this.checkStringIfValidEmail()) {
          notify.error(this.$t('invalid_email'));
          return;
        }
        await this.makeApiCall();
      } catch (err) {
        let msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        if (msg.includes('undefined')) {
          msg = ApiExceptions.translate('INVALID_SUPPORT_EMAIL');
        }
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    async makeApiCall() {
      const formData = this.buildRequestBody();
      return await supportApiService
        .create_ticket(formData)
        .then((response) => {
          this.hideLoading();
          notify.success(this.$t('success'));
        })
        .catch((response) => {
          this.hideLoading();
          if (response.message.error.includes('customer')) {
            notify.error(
              this.$t('no_email_found') + ' ' + this.supportTicket.email,
            );
          } else {
            notify.error(this.$t('errors_INVALID_AUTHORIZATION_CODE'));
          }
        });
    },
  },
});
</script>

<style lang="scss" scoped>
.container-height {
  overflow-y: scroll;
}
</style>
